function dotsKeep(l,keep){
return l.map(function(x){
var k=0;
return x.replace(/[…‥]+/g,function(m,at,all){
k++;
if(keep(k))return m;
var prev=all.charAt(at-1),next=all.charAt(at+m.length);
if(!prev|| /[。！？!?、「\s♡]/.test(prev)|| !next|| /[。！？!?、」\s♡]/.test(next))return'';
return'、';
}).replace(/、{2,}/g,'、').replace(/^[、\s]+/,'').replace(/、(?=[♡！!？?]|$)/g,'');
}).filter(function(x){return x.replace(/[…‥、。！？!?♡\s]/g,'').length>0;});
}
function half(l){return dotsKeep(l,function(k){return k%2===1;});}
function one(l){return dotsKeep(l,function(k){return k===1;});}
