T.ffTools=function(s,climax){
var t={},MUT=HK.Pos&&HK.Pos.MUTUAL_RE;
if(/舌|吸い上げ|唇で|口に含|顔を埋|顔を寄せ/.test(s))t.tongue=1;
if(/指|手を伸ば|片手で/.test(s))t.finger=1;
if((MUT&&MUT.test(s))|| /擦れ合|脚を交差|脚を絡めたまま/.test(s))t.mutual=1;
if(/玩具/.test(s))t.toy=1;
if(!climax&& !t.tongue&& !t.mutual)t.finger=1;
return t;
};
T.ffClimaxFor=function(g,body){
var list=T.FF_CLIMAX[g]||T.FF_CLIMAX.soft,bt=T.ffTools(body||'');
var ok=list.filter(function(c){
var ct=T.ffTools(c,true);
if(ct.mutual)return!!bt.mutual;
if(ct.toy)return!!bt.toy;
if(!ct.tongue&& !ct.finger)return true;
return!!((ct.tongue&&bt.tongue)||(ct.finger&&bt.finger));
});
return ok.length?ok:list;
};
