free:[L('それ、いい……っ、もっと！|やば、気持ちいい……っ|ちょ、くすぐった……っ、あ……っ|ん、ぁっ……それ、すき……っ|もっと、もっと……っ、そこ……っ'),L('イく、イっちゃう……っ！|あ、あ……っ、気持ちいい……っ！|もう、わけ、わかんない……っ|あっ、あっ……っ、またイく……っ！|すご、い……っ、とまんない……っ')],
